function player(series,list){return '<div class="player '+(series?'series':'')+'"><div class="phead"><span><span class="back">‹</span> '+(series?'المسلسلات / The Last of Us':'القنوات / beIN SPORTS 1')+'</span><span class="gold">جمرة &nbsp; ◇</span></div><div class="pcontrols" style="'+(list?'left:620px':'')+'"><div class="quality">'+(series?'THE JAMRA COLLECTION':'<span style="color:#FF3B5C">● LIVE</span> &nbsp;&nbsp; 4K UHD · 50 FPS')+'</div><h1>'+(series?'The Last of Us':'beIN SPORTS 1')+'</h1><span style="font-size:18px;color:#C9B3A6">'+(series?'الموسم الأول · الحلقة 3':'عالمك الرياضي، مباشرة')+'</span>'+(series?'<div class="progress"><i></i></div><div class="pfoot"><span>00:24:18 / 00:54:32</span><div class="playbuttons"><div class="circlewrap"><span class="circle prw">↶</span>ترجيع 10 ث</div><div class="circlewrap"><span class="circle pause focused">Ⅱ</span><span class="plabel">إيقاف مؤقت</span></div><div class="circlewrap"><span class="circle pff">↷</span>تقديم 10 ث</div></div><div class="circlewrap ptracks"><span class="circle">♬</span>الصوت والترجمة</div></div>':'<div class="livebuttons">'+[['▤','القنوات'],['♡','المفضلة'],['4K','الجودة']].map((a,i)=>'<div class="circlewrap"><div class="circle '+(!i?'focus focused':'')+'">'+a[0]+'</div>'+a[1]+'</div>').join('')+'</div>')+'</div>'+(list?'<div class="drawer"><div class="eyebrow">LIVE CHANNELS</div><h2>قنواتك، في متناولك</h2><div class="tiny" style="margin-bottom:26px">كل القنوات &nbsp; · &nbsp; 128 قناة</div>'+channels()+'<div class="tiny" style="position:absolute;bottom:40px">⤺ إغلاق القائمة &nbsp; &nbsp; ↵ مشاهدة</div></div>':'')+'</div>'}
